-- NPCBots chatter texts, deDE, see src/server/game/AI/NpcBots/botchatter.h
-- slot N here translates slot N of the same npc_text ID
SET @CHATTER_TEXTS_START = 71001;
SET @CHATTER_TEXTS_END   = 71100;

DELETE FROM `npc_text_locale` WHERE `Locale`='deDE' AND `ID` BETWEEN @CHATTER_TEXTS_START AND @CHATTER_TEXTS_END;
